head.script:
///////// 1. 변수 및 선언 영역 /////////
/*
 * 화면 동작
 *  - 부모(ETN 마감 ULDSTF08200 — AS-IS ULDSTF08306)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정 모드다.
 *  - 신규는 부모가 넘긴 종목(또는 [종목선택] 팝업으로 고른 종목 목록)을 그리드에 두고, 종목마다 중복을 확인한 뒤 한 건씩 등록한다.
 *  - 수정·삭제도 그리드의 종목을 한 건씩 보낸다. 삭제가 모두 성공하면 팝업을 닫고, 부모는 await 가 끝나면 목록을 다시 조회한다.
 *  - 조회기준일이 서버 현재일보다 앞이면 조회 전용(버튼 모두 잠금)이다.
 *  - 공시안내문작성(ULDSTF92024)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #7).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08304/ULDSTF08304.md (§번호는 이 문서의 절)
 */
scwin.screenId = "ULDSTF08304";

// 부모 화면에서 넘겨받는 값 (§1.2)
scwin.isuCd = "";           // 부모 목록에서 고른 종목코드 (AS-IS arr[0] Isu_cd) — 있으면 종목선택 잠금
scwin.isuNm = "";           // 부모 목록에서 고른 종목명 (AS-IS arr[1] Isu_nm)
scwin.secugrpId = "";       // 증권그룹ID EN: ETN, EF: ETF (AS-IS arr[2] Secugrp_id)
scwin.bzProcsNo = "";       // 업무처리번호 — 비면 신규, 있으면 수정 (AS-IS arr[4] fr_bz_procs_no). 신규 등록 성공 뒤 확정
scwin.designDd = "";        // 지정연장일 기본값 (AS-IS arr[5] design_dd)
scwin.inqDd = "";           // 조회기준일 — 중복확인·저장의 기준일, 현재일보다 앞이면 조회 전용 (AS-IS arr[6] Inq_dd)
scwin.fstDtectDd = "";      // 최초적출일 — 추가여부 Y 가 아닌 종목의 최초지정일 (AS-IS arr[7] fst_dtect_dd)
scwin.isurCd = "";          // 부모 목록에서 고른 종목의 발행기관코드 (AS-IS arr[8] Isur_cd)

// 화면 상태값
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 yyyyMMdd (AS-IS fn_todayDate 의 TODAY_DD)
scwin.selectedRow = -1;     // 그리드에서 클릭한 행 (AS-IS selectedGrdNum — 0 이 "선택 없음", TO-BE 는 -1)
scwin.dsclRow = -1;         // 공시안내문작성 대상 행 — 호환용 scwin.getPar 가 읽는다
scwin.processing = false;   // 저장·수정·삭제 진행 중 — 행 단위 순차 전송 중에 다시 누르지 못하게(§8 #11)

// 고정값
scwin.DESIGN_CD = "04";                 // ETP투자유의지정코드 04: 지정연장 (AS-IS etp_Invstwarn_design_cd)
scwin.COMPLETE_YN_OK = "Y";             // 등록·수정·삭제 응답 completeYn 의 성공 값 — TODO: 명세에 값이 없어 가정 (§10 #4)
scwin.DSCL_FORM_CD = {                  // 공시안내문 서식코드 (AS-IS fn_dscl 의 discls_form_cd)
    EN : "68393",                       // 상장지수증권 투자유의종목 지정연장 안내공시
    EF : "99359"                        // ETF 투자유의종목 지정연장
};
scwin.DSCL_MKT_ID = "1";                // 공시안내문 시장구분 (AS-IS arr[3] = '1')

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 서버 현재일 → 달력 바인딩 → 종목선택 활성 → 모드 분기(신규 기본값 / 수정 상세 조회).
 * (원본 gform onload + fn_onload + dts_Mst·dts_Isu_Temp OnLoadCompleted — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 상세 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) 배열 9칸 (§1.2)
    //    arr[3] Mkt_id 는 이 화면에서 쓰지 않아 받지 않는다(§8 #10).
    const param = $c.data.getParameter() ?? {};

    scwin.isuCd = String(param.isuCd ?? "");
    scwin.isuNm = String(param.isuNm ?? "");
    scwin.secugrpId = String(param.secugrpId ?? "");
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.designDd = String(param.designDd ?? "");
    scwin.inqDd = String(param.inqDd ?? "");
    scwin.fstDtectDd = String(param.fstDtectDd ?? "");
    scwin.isurCd = String(param.isurCd ?? "");

    // 3) 서버 현재일 — 원본 fn_todayDate(동기 조회 invstwarn_today_dd). 명세에 없어 gcc 서버 시각으로 대신한다(§10 #8).
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 4) 달력 검사 바인딩(1회) — 단일 달력(규칙 37)
    $c.date.checkCalendarFormat(edt_DesignDd, "yyyyMMdd");

    // 5) 종목선택 활성 — 업무처리번호나 부모 종목이 있으면 잠근다(원본 onload 의 fn_SetIsuCdBtnShow)
    scwin.setIsuCdBtnShow();

    // 6) 모드 분기 — 원본 fn_onload
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    await scwin.selectOne();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [종목선택] 버튼 클릭 (원본 img_SetIsuCd onclick — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_isuTemp_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 지정연장종목 그리드 셀 클릭 — 공시안내문작성 대상 행을 기억한다. (원본 grid_1 OnClick → fn_SelectGridRow — §4)
 * @param {Number} rowIndex 행 index
 * @param {Number} columnIndex 열 index
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_isuTemp_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.selectedRow = rowIndex;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08304.grd_isuTemp_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [저장] 버튼 클릭 (원본 buttonSet.setSaveInfo(btn_Save, fn_save) — §6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [수정] 버튼 클릭 (원본 buttonSet.setUpdateInfo(btn_Update, fn_update) — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [삭제] 버튼 클릭 (원본 buttonSet.setDeleteInfo(btn_Delete, fn_delete) — §6.7)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [안내문작성] 버튼 클릭 (원본 buttonSet.setDsclInfo(btn_Dscl, fn_dscl) — §6.10)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08304.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 모드 상세 조회. 응답을 dma_detail 에 담고 그 종목을 그리드 한 행으로 둔 뒤, 조회기준일로 버튼 상태를 정한다.
 * (원본 fn_onload 의 dts_Mst 조회 + dts_Mst OnLoadCompleted 수정 분기 — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    // TODO: AS-IS 는 GUBUN_CD=04(지정연장)도 보냈다 — 명세 요청에 없어 보내지 않는다(§10 #3)
    const requestData = {
        secugrpId : scwin.secugrpId,
        bzProcsNo : scwin.bzProcsNo
    };

    dma_detail.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패했거나 조회된 종목이 없으면 버튼을 잠근 채 둔다(※TO-BE — §8 #12).
    if (!result.responseJSON?.success || $c.util.isEmpty(dma_detail.get("isuCd"))) {
        // TODO: 가정 문구 (§10 #10)
        await $c.win.alert("상세 내역을 찾을 수 없습니다.");
        return;
    }

    // 원본 CopyDataSet(dts_Mst, dts_Isu_Temp) — 조회한 종목을 그리드 한 행으로
    dlt_isuTemp.setJSON([{
        isuCd : dma_detail.get("isuCd"),
        isuNm : dma_detail.get("isuNm"),
        isurCd : dma_detail.get("isurCd"),
        bzProcsNo : dma_detail.get("bzProcsNo"),
        addYn : dma_detail.get("addYn"),
        comNm : "",                 // TODO: 명세 select-one 응답에 발행기관명이 없다(§10 #7)
        status : ""
    }]);
    scwin.selectedRow = -1;
    scwin.bzProcsNo = dma_detail.get("bzProcsNo");

    scwin.setIsuCdBtnShow();

    // 조회기준일이 현재일보다 앞이면 조회 전용 (원본 Inq_dd < today_dd → setDisableStatus)
    const status = (scwin.inqDd < scwin.curDate) ? "disabled" : "update";
    $c.util.setButtonState("grpBtnBox", status, scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.checkDuplicate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드의 종목마다 같은 기준일에 지정연장(04)이 이미 저장돼 있는지 확인한다. 하나라도 중복이면 안내하고 true.
 * (원본 fn_duplicate_check — 행마다 동기 조회 — §5.2)
 * @returns {Promise<Boolean>} 중복(또는 확인 실패) 여부 — true 면 저장하지 않는다
 * @hidden N
 */
scwin.checkDuplicate = async function () {
    const rowCount = dlt_isuTemp.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        const sbmOptions = {
            id : "sbm_checkDuplicate",
            method : "get",
            action : "/api/listing/lstproc/etn/invstwarn/select-check-duplicate",
            isProcessMsg : false
        };

        const requestData = {
            etpInvstwarnDesignCd : scwin.DESIGN_CD,
            basDd : scwin.inqDd,
            isuCd : dlt_isuTemp.getCellData(i, "isuCd")
        };

        const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
        if (result?.skipped) return true;   // 진행 중 확인이 있어 이번 호출은 건너뜀 — 저장하지 않는다

        if (!result.responseJSON?.success) {
            // TODO: 가정 문구 — 원본은 확인 실패를 중복 아님으로 넘겼다(§8 #6, §10 #10)
            await $c.win.alert("중복 확인에 실패했습니다.");
            return true;
        }

        // TODO: 명세는 응답 최상위 dupChk 를 읽는다(body 아님) — 응답 구조 확인 (§10 #2)
        if (result.responseJSON.dupChk === "Y") {
            await $c.win.alert("중복된 종목이 저장되어 있습니다.");
            return true;
        }
    }
    return false;
};

/**
 * @method
 * @name scwin.selectFstDesignDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목의 최초지정일자를 조회한다. (원본 fn_Instwarn_fstdd 의 dts_Instwarn 동기 조회 — §5.3)
 * @param {String} isuCd 종목코드
 * @returns {Promise<String>} 최초지정일자 (없거나 실패면 빈 문자열)
 * @hidden N
 */
scwin.selectFstDesignDd = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectFstDesignDd",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-fst-design-dd",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped || !result.responseJSON?.success) return "";

    // TODO: 명세는 응답 최상위 fstDesignDd 를 읽는다(body 아님) — 응답 구조 확인 (§10 #2)
    return String(result.responseJSON.fstDesignDd ?? "");
};

/**
 * @method
 * @name scwin.sendRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 등록(I)·수정(U)·삭제(D)하고 결과를 그 행의 status 에 남긴다.
 * 행 값은 먼저 dma_detail(원본 dts_Mst)에 옮기고, 처리별 명세 전문(dma_register·dlt_register / dma_update / dma_delete)을 만든다.
 * 등록은 업무처리번호를 비워 보내 서버가 채번하고, 성공하면 응답 번호를 그 행에 기록한다.
 * (원본 fn_copy_dts + fn_save_trs + trs OnSuccess/OnFail 의 행 처리 — §5.4~§5.6)
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
 */
scwin.sendRow = async function (trJob, row) {
    await scwin.copyRowToDetail(trJob, row);

    let sbmOptions;
    let requestData;

    if (trJob === "I") {
        sbmOptions = {
            id : "sbm_sendRow",
            method : "post",
            action : "/api/listing/lstproc/etn/invstwarn/register",
            target : "dma_resultSave=body",
            mediatype : "application/json",
            isProcessMsg : false
        };
        // 원본은 행마다 화면에서 채번(fn_getNewBzProcNo)했다 — 명세 register 는 비우면 서버 채번(§5.4, §10 #5).
        // 최초지정일이 행마다 다를 수 있어(추가여부 Y) 한 건씩 보낸다(isuList 1행 — §10 #5).
        dma_register.setJSON({
            secugrpId : scwin.secugrpId,
            etpInvstwarnDesignCd : dma_detail.get("etpInvstwarnDesignCd"),
            designDd : dma_detail.get("designDd"),
            designRsn : dma_detail.get("designRsn"),
            etpInvstwarnContn : dma_detail.get("etpInvstwarnContn"),
            misc : dma_detail.get("misc"),
            basDd : dma_detail.get("basDd"),
            fstDesignDd : dma_detail.get("fstDesignDd")
        });
        dlt_register.setJSON([{
            bzProcsNo : "",
            isuCd : dma_detail.get("isuCd"),
            isurCd : dma_detail.get("isurCd"),
            addYn : dma_detail.get("addYn")
        }]);
        requestData = {
            ...dma_register.getJSON(),
            isuList : dlt_register.getAllJSON()     // 등록 종목 목록 (AS-IS dts_Isu_Temp)
        };
    } else if (trJob === "U") {
        sbmOptions = {
            id : "sbm_sendRow",
            method : "post",
            action : "/api/listing/lstproc/etn/invstwarn/modify",
            ref : "dma_update",
            target : "dma_resultSave=body",
            mediatype : "application/json",
            isProcessMsg : false
        };
        dma_update.setJSON({
            bzProcsNo : dma_detail.get("bzProcsNo"),
            secugrpId : scwin.secugrpId,
            isuCd : dma_detail.get("isuCd"),
            isurCd : dma_detail.get("isurCd"),
            designDd : dma_detail.get("designDd"),
            designRsn : dma_detail.get("designRsn"),
            etpInvstwarnContn : dma_detail.get("etpInvstwarnContn"),
            misc : dma_detail.get("misc"),
            addYn : dma_detail.get("addYn"),
            basDd : dma_detail.get("basDd"),
            etpInvstwarnDesignCd : dma_detail.get("etpInvstwarnDesignCd"),
            fstDesignDd : dma_detail.get("fstDesignDd")
        });
    } else {
        sbmOptions = {
            id : "sbm_sendRow",
            method : "post",
            action : "/api/listing/lstproc/etn/invstwarn/remove",
            ref : "dma_delete",
            target : "dma_resultSave=body",
            mediatype : "application/json",
            isProcessMsg : false
        };
        dma_delete.setJSON({
            bzProcsNo : dma_detail.get("bzProcsNo"),
            secugrpId : scwin.secugrpId,
            isuCd : dma_detail.get("isuCd"),
            isurCd : dma_detail.get("isurCd")
        });
    }

    dma_resultSave.setEmptyValue();
    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다. 원본 trs OnFail(alert_error 후 다음 행 계속)처럼
    // 그 행만 실패로 남기고 다음 행으로 간다 — 마지막 결과 안내·삭제 성공 행 제거가 돌게 한다(§6.8).
    let result;
    try {
        result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    } catch (ex) {
        dlt_isuTemp.setCellData(row, "status", "N");
        return false;
    }

    // TODO: completeYn 의 성공 값("Y")은 가정 — 명세 확인 필요 (§10 #4). 값이 비어 오면 success 만으로 판정한다.
    const completeYn = String(dma_resultSave.get("completeYn") ?? "");
    const isSuccess = (result?.skipped !== true && result.responseJSON?.success === true
        && (completeYn === "" || completeYn === scwin.COMPLETE_YN_OK));

    if (isSuccess && trJob === "I") {
        // 원본 OnSuccess: dts_Isu_Temp.BZ_PROCS_NO = fr_bz_procs_no — 성공한 행에만 번호를 남긴다(§8 #9)
        const bzProcsNo = scwin.getRegBzProcsNo();
        dlt_isuTemp.setCellData(row, "bzProcsNo", bzProcsNo);
        dma_detail.set("bzProcsNo", bzProcsNo);
    }
    dlt_isuTemp.setCellData(row, "status", isSuccess ? "Y" : "N");

    return isSuccess;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 기본값. 지정연장일은 부모가 넘긴 값, 지정연장사유·투자유의사항·기타는 표준 문구.
 * 부모가 종목을 넘겼으면 그 종목을 그리드 한 행으로 둔다. 통신 없음.
 * (원본 fn_onload 의 헤더 조회 + dts_Mst·dts_Isu_Temp OnLoadCompleted 신규 분기 — §6.1, §5.7)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_detail.setEmptyValue();
    dlt_isuTemp.removeAll();
    scwin.selectedRow = -1;

    dma_detail.set("designDd", scwin.designDd);
    dma_detail.set("designRsn", "투자유의종목 지정단위기간(3매매거래일) 장종료시 실시간 괴리율이\n"
        + "규정상 관리의무 비율을 1일 이상 초과에 해당");
    dma_detail.set("etpInvstwarnContn", "투자유의종목 지정이 연장됨에 따라 지정연장일부터 새로운 투자유의종목 지정단위기간이\n"
        + "시작됩니다. 투자유의종목 지정단위기간 중 장종료시 실시간 괴리율이 규정상 의무범위를 \n"
        + "1일 이상 초과하는 경우 투자유의종목 지정이 재연장될 수 있습니다.\n"
        + "또한, 지정단위기간 종료일의 장종료시 실시간 괴리율이 규정상 의무범위의 3배를 이상인 경우\n"
        + "매매거래가 정지될 수 있습니다.");
    dma_detail.set("misc", "-");

    // 원본 dts_Isu_Temp OnLoadCompleted — 신규인데 부모 종목이 있으면 한 행 (추가여부는 비움)
    if (!$c.util.isEmpty(scwin.isuCd)) {
        dlt_isuTemp.setJSON([{
            isuCd : scwin.isuCd,
            isuNm : scwin.isuNm,
            isurCd : scwin.isurCd,
            bzProcsNo : "",
            addYn : "",
            comNm : "",
            status : ""
        }]);
    }
};

/**
 * @method
 * @name scwin.setIsuCdBtnShow
 * @author Inswave
 * @date 2026. 10. 28
 * @description [종목선택] 활성. 업무처리번호가 있거나(수정·저장 후) 부모가 종목을 넘겼으면 잠근다. (원본 fn_SetIsuCdBtnShow — §6.2)
 * @returns
 * @hidden N
 */
scwin.setIsuCdBtnShow = function () {
    img_SetIsuCd.setDisabled(!$c.util.isEmpty(scwin.bzProcsNo) || !$c.util.isEmpty(scwin.isuCd));
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목선택 팝업(ETN ULDSTF08045 / ETF ULDSTF08047)을 열고, 고른 종목 목록으로 그리드를 바꾼다. 고른 종목은 모두 추가여부 Y.
 * (원본 img_SetIsuCd onclick + fn_GetParIsu / fn_SetParIsu + fn_PopFindEtnCode / fn_PopFindEtfCode — §6.3, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // 원본은 증권그룹이 EN·EF 가 아니면 아무것도 열지 않는다.
    const popupId = { EN : "ULDSTF08045", EF : "ULDSTF08047" }[scwin.secugrpId];
    if (!popupId) return;

    const data = {
        isurCd : "",                                // AS-IS arrPar[0] = ""
        secugrpId : scwin.secugrpId,                // AS-IS fn_PopFindEtfCode(Secugrp_id) 인자
        gubun : "3",                                // AS-IS arrPar[1] = "3" (상장전체)
        selList : dlt_isuTemp.getAllJSON()          // AS-IS CopyDataSet(dts_Isu_Temp, param_dts) — TODO: 08045 전환본이 받지 않음 (§10 #6)
    };
    const options = {
        id : popupId,
        popupName : "종목선택",
        width : 800,
        height : 650,
        type : "pageFramePopup"
    };

    // TODO: 경로·크기는 가정 — ETF 종목선택(ULDSTF08047)은 전환본 없음 (§10 #6)
    const url = (popupId === "ULDSTF08045") ? "/ui/lst/common/ULDSTF08045.xml" : "/ui/lst/common/ULDSTF08047.xml";
    const result = await $c.win.openPopup(url, options, data);

    // [확인]은 고른 종목 배열을 돌려준다. 취소·닫기(X)·ESC 는 { isCloseButtonClick } 객체라 배열이 아니다.
    if (!Array.isArray(result) || result.length === 0) return;

    // 원본 fn_SetParIsu — 그리드를 통째로 바꾸고 모두 추가여부 Y
    dlt_isuTemp.setJSON(result.map(isu => ({
        isuCd : isu.isuCd ?? "",
        isuNm : isu.isuNm ?? "",
        isurCd : isu.isurCd ?? "",
        bzProcsNo : "",
        addYn : "Y",
        comNm : isu.comNm ?? "",
        status : ""
    })));
    scwin.selectedRow = -1;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정 전 입력 검증. 종목(그리드 행) 유무를 먼저 보고, 지정연장일 필수·날짜 형식은 공통 검증으로 본다. (원본 fn_CheckForm — §6.4)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isuTemp.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    const options = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_DesignDd : { required : true, format : "date", name : "지정연장일" }
        }
    };
    return await $c.validate.validateDataCollect(panel_3, options);
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 저장. 검증 → 종목 중복 확인 → 저장 확인 → 행마다 등록 (원본 fn_save — §6.5, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    if (scwin.processing) return;
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    if (await scwin.checkDuplicate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 수정 확인 → 행마다 수정 (원본 fn_update — §6.6, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    if (scwin.processing) return;
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 삭제 확인 → 행마다 삭제. 입력 검증은 하지 않는다. (원본 fn_delete — §6.7, §1.4 업무 5)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    if (scwin.processing) return;
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.processRows(scwin.trJob);
};

/**
 * @method
 * @name scwin.processRows
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드의 종목을 한 건씩 순차 전송하고 결과를 한 번 안내한 뒤 화면 상태를 맞춘다.
 *  - 한 건이라도 실패하면 MSG-A002. 삭제는 성공한 행을 그리드에서 지워 실패한 행만 남긴다.
 *  - 모두 성공하면 MSG-A001. 삭제는 팝업을 닫고, 저장은 수정 모드로 바꾼다. 부모 재조회는 팝업이 닫힌 뒤 부모가 한다.
 * (원본 fn_save·fn_update·fn_delete 의 행 반복 + trs OnSuccess/OnFail 의 trsCnt == trsTotalCnt 분기 — §6.8)
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @returns
 * @hidden N
 */
scwin.processRows = async function (trJob) {
    const rowCount = dlt_isuTemp.getRowCount();
    if (rowCount === 0) return;     // 원본도 보낼 행이 없으면 아무 안내 없이 끝난다

    const jobNm = { I : "저장", U : "수정", D : "삭제" }[trJob];
    let errCnt = 0;

    scwin.processing = true;
    try {
        for (let i = 0; i < rowCount; i++) {
            if (!await scwin.sendRow(trJob, i)) errCnt++;
        }
    } finally {
        scwin.processing = false;
    }

    if (errCnt > 0) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));

        // 원본 OnFail(삭제) — 성공한 행(status Y)을 지운다. 뒤에서부터 지워야 index 가 밀리지 않는다.
        if (trJob === "D") {
            dlt_isuTemp.setBroadcast(false);
            for (let i = dlt_isuTemp.getRowCount() - 1; i >= 0; i--) {
                if (dlt_isuTemp.getCellData(i, "status") === "Y") dlt_isuTemp.removeRow(i);
            }
            dlt_isuTemp.setBroadcast(true, true);
            scwin.selectedRow = -1;
        }
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    if (trJob === "D") {
        $c.win.closePopup();
        return;
    }

    // 원본 OnSuccess — 한 행이면 그 행을 선택한 상태로, 저장이면 수정 모드 + 종목선택 잠금
    if (dlt_isuTemp.getRowCount() === 1) scwin.selectedRow = 0;
    scwin.bzProcsNo = dlt_isuTemp.getCellData(0, "bzProcsNo");

    if (trJob === "I") {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
        scwin.setIsuCdBtnShow();
    }
};

/**
 * @method
 * @name scwin.copyRowToDetail
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행의 종목과 화면 고정값을 dma_detail(원본 dts_Mst)에 옮긴다.
 * 지정연장일·사유·투자유의사항·기타는 입력이 dma_detail 에 바인딩돼 이미 들어 있다.
 * 저장·수정은 최초지정일을 정한다 — 추가여부 Y 면 서버 조회(없으면 지정연장일), 아니면 부모가 넘긴 최초적출일.
 * (원본 fn_copy_dts + fn_save_trs 의 dts_Mst 채우기 — §6.9)
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @param {Number} row 그리드 행 index
 * @returns
 * @hidden N
 */
scwin.copyRowToDetail = async function (trJob, row) {
    const isu = dlt_isuTemp.getRowJSON(row);

    // 원본 fn_save 는 신규 행마다 새 번호를, fn_update·fn_delete 는 행의 번호를 쓴다 — 신규는 서버 채번이라 빈 값
    dma_detail.set("bzProcsNo", (trJob === "I") ? "" : isu.bzProcsNo);
    dma_detail.set("isuCd", isu.isuCd);
    dma_detail.set("isuNm", isu.isuNm);
    dma_detail.set("isurCd", isu.isurCd);
    dma_detail.set("addYn", isu.addYn);
    dma_detail.set("etpInvstwarnDesignCd", scwin.DESIGN_CD);
    dma_detail.set("basDd", scwin.inqDd);

    // 삭제는 명세 remove 요청에 최초지정일이 없어 조회하지 않는다(원본은 삭제에도 조회 — §8 #8).
    if (trJob !== "D") {
        dma_detail.set("fstDesignDd", await scwin.getFstDesignDd(isu));
    }
};

/**
 * @method
 * @name scwin.getFstDesignDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 행의 최초지정일. 추가여부 Y(종목선택으로 추가한 종목)면 종목의 최초지정일자를 조회하고, 없으면 지정연장일.
 * 그 밖에는 부모가 넘긴 최초적출일. (원본 fn_save_trs 의 ADD_YN 분기 + fn_Instwarn_fstdd — §6.9, §5.3)
 * @param {Object} isu 그리드 행 JSON
 * @returns {Promise<String>} 최초지정일자
 * @hidden N
 */
scwin.getFstDesignDd = async function (isu) {
    if (isu.addYn !== "Y") return scwin.fstDtectDd;

    const fstDesignDd = await scwin.selectFstDesignDd(isu.isuCd);
    return $c.util.isEmpty(fstDesignDd) ? dma_detail.get("designDd") : fstDesignDd;
};

/**
 * @method
 * @name scwin.getRegBzProcsNo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록 응답에서 서버가 채번한 업무처리번호를 꺼낸다. 한 건씩 보내므로 bzProcsNoList 의 첫 값, 없으면 bzProcsNo. (§5.4)
 * @returns {String} 업무처리번호
 * @hidden N
 */
scwin.getRegBzProcsNo = function () {
    // TODO: bzProcsNoList 는 명세 dataType text — 배열·쉼표 문자열 어느 쪽인지 확인 (§10 #5). 지금은 둘 다 받는다.
    const list = dma_resultSave.get("bzProcsNoList");
    const first = Array.isArray(list) ? list[0] : String(list ?? "").split(",")[0];
    return String(first ?? "").trim() || String(dma_resultSave.get("bzProcsNo") ?? "");
};

/**
 * @method
 * @name scwin.getDsclRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성 대상 행. 한 행이면 그 행, 여러 행이면 그리드에서 클릭한 행. (원본 fn_dscl 의 selectedGrdNum 판정 — §6.10)
 * @returns {Number} 행 index (대상이 없으면 -1)
 * @hidden N
 */
scwin.getDsclRow = function () {
    const rowCount = dlt_isuTemp.getRowCount();
    if (rowCount === 1) return 0;
    if (scwin.selectedRow >= 0 && scwin.selectedRow < rowCount) return scwin.selectedRow;
    return -1;
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋이다. (§6.10)
 * isu 는 대상 행(원본 dts_Isu), mst 는 dma_detail 위에 대상 행 종목과 발행기관명을 덮은 1행(원본 dts_Mst + COM_NM)이다.
 * @param {Number} row 대상 행 index
 * @returns {Object} 넘길 data (증권그룹이 EN·EF 가 아니면 null)
 * @hidden N
 */
scwin.getDsclData = function (row) {
    const formCd = scwin.DSCL_FORM_CD[scwin.secugrpId];
    if (!formCd || row < 0) return null;

    const isu = dlt_isuTemp.getRowJSON(row);
    const isuRow = {
        bzProcsNo : isu.bzProcsNo,
        isuCd : isu.isuCd,
        isuNm : isu.isuNm,
        isurCd : isu.isurCd,
        addYn : isu.addYn
    };

    return {
        formCd : formCd,                                            // AS-IS arr[0] discls_form_cd
        bzProcsNo : isu.bzProcsNo,                                  // AS-IS arr[1] fr_bz_procs_no
        isurCd : isu.isurCd,                                        // AS-IS arr[2] Isur_cd
        mktId : scwin.DSCL_MKT_ID,                                  // AS-IS arr[3] '1'
        isuNm : (scwin.secugrpId === "EN") ? isu.isuNm : "",        // AS-IS arr[5] (ETF 는 "")
        isu : [isuRow],                                             // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        mst : [{ ...dma_detail.getJSON(), ...isuRow, comNm : isu.comNm }]   // AS-IS CopyDataSet(dts_Mst, param_dts_mst) + COM_NM
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 돌려받는 값은 없다. 확인 메시지는 없다(원본 그대로).
 * (원본 fn_dscl — §6.10, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const row = scwin.getDsclRow();
    if (row < 0) {
        await $c.win.alert("종목을 선택해 주세요.");
        return;
    }

    const data = scwin.getDsclData(row);
    if (!data) {
        // TODO: 가정 문구 — 원본은 EN·EF 밖이면 빈 서식코드로 열었다 (§8 #14, §10 #10)
        await $c.win.alert("안내문을 작성할 수 없는 증권그룹입니다.");
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 825,
        type : "pageFramePopup"
    };

    scwin.dsclRow = row;
    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, data);
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 28
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.10, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [5] 종목명 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList (원본 param_dts_isu)
 * @param {Object} dltMst 92024 의 마스터 dataList (원본 param_dts_mst)
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    const data = scwin.getDsclData(scwin.dsclRow);
    if (!data) return arr.length;

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[5] = data.isuNm;            // 원본도 arr[4] 는 채우지 않는다

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
